/** Message protocol for running the dental network in a Web Worker (keeps the UI thread free). Pure, so it is unit-testable. */
import type { NetOutputs, NetRunner } from '@core/perception/pipeline';
export type ToWorker = { type: 'init'; model: ArrayBuffer } | { type: 'run'; id: number; chw: Float32Array };
export type FromWorker = { type: 'ready' } | { type: 'result'; id: number; seg: Float32Array; ident: Float32Array; kp: Float32Array } | { type: 'error'; id?: number; message: string };
export interface PortLike { postMessage(msg: unknown, transfer?: Transferable[]): void; onmessage: ((e: { data: never }) => void) | null; terminate?(): void }

/** Worker side: wires a NetRunner factory to messages. */
export function workerHandler(load: (model: ArrayBuffer) => Promise<NetRunner>, post: (m: FromWorker, t?: Transferable[]) => void): (m: ToWorker) => Promise<void> {
  let net: NetRunner | null = null;
  return async (m) => {
    try {
      if (m.type === 'init') { net = await load(m.model); post({ type: 'ready' }); return; }
      if (!net) throw new Error('worker not initialised');
      const o = await net.run(m.chw);
      post({ type: 'result', id: m.id, seg: o.seg, ident: o.ident, kp: o.kp }, [o.seg.buffer, o.ident.buffer, o.kp.buffer] as Transferable[]);
    } catch (e) { post({ type: 'error', ...(m.type === 'run' ? { id: m.id } : {}), message: (e as Error).message }); }
  };
}

/** Main-thread side: a NetRunner that proxies to the worker with request ids, a timeout, and clean failure. */
export function createWorkerNetRunner(worker: PortLike, model: ArrayBuffer, timeoutMs = 20000): Promise<NetRunner> {
  const pending = new Map<number, { res: (o: NetOutputs) => void; rej: (e: Error) => void; t: ReturnType<typeof setTimeout> }>();
  let next = 1, failed: Error | null = null;
  return new Promise<NetRunner>((resolve, reject) => {
    const initTimer = setTimeout(() => reject(new Error('inference worker did not start')), timeoutMs);
    const fail = (e: Error) => { failed = e; for (const p of pending.values()) { clearTimeout(p.t); p.rej(e); } pending.clear(); };
    worker.onmessage = (ev) => {
      const m = ev.data as FromWorker;
      if (m.type === 'ready') { clearTimeout(initTimer); resolve(runner); }
      else if (m.type === 'result') { const p = pending.get(m.id); if (p) { clearTimeout(p.t); pending.delete(m.id); p.res({ seg: m.seg, ident: m.ident, kp: m.kp }); } }
      else if (m.type === 'error') { if (m.id !== undefined) { const p = pending.get(m.id); if (p) { clearTimeout(p.t); pending.delete(m.id); p.rej(new Error(m.message)); } } else { clearTimeout(initTimer); fail(new Error(m.message)); reject(new Error(m.message)); } }
    };
    const runner: NetRunner = {
      run(chw) {
        if (failed) return Promise.reject(failed);
        return new Promise<NetOutputs>((res, rej) => { const id = next++; const t = setTimeout(() => { pending.delete(id); rej(new Error('inference timed out')); }, timeoutMs); pending.set(id, { res, rej, t }); worker.postMessage({ type: 'run', id, chw } satisfies ToWorker, [chw.buffer]); });
      },
    };
    worker.postMessage({ type: 'init', model } satisfies ToWorker);
  });
}
