/// <reference lib="webworker" />
import { createNetRunner } from './ort';
import { workerHandler, type ToWorker } from './netProtocol';
const handle = workerHandler(createNetRunner, (m, t) => (self as unknown as Worker).postMessage(m, t ?? []));
self.onmessage = (e: MessageEvent<ToWorker>) => { void handle(e.data); };
