import * as ort from 'onnxruntime-web/wasm';
import type { NetRunner, NetOutputs } from '@core/perception/pipeline';

/** ONNX Runtime Web (WASM). Multi-threading only when the page is cross-origin isolated; otherwise single-threaded. */
export async function createNetRunner(model: ArrayBuffer): Promise<NetRunner> {
  ort.env.wasm.wasmPaths = `${import.meta.env.BASE_URL}ort/`;
  ort.env.wasm.numThreads = typeof crossOriginIsolated !== 'undefined' && crossOriginIsolated ? Math.min(4, navigator.hardwareConcurrency || 2) : 1;
  const session = await ort.InferenceSession.create(new Uint8Array(model), { executionProviders: ['wasm'], graphOptimizationLevel: 'all' });
  // warm-up so the first live frame is not slow
  await session.run({ image: new ort.Tensor('float32', new Float32Array(3 * 128 * 192).fill(0.5), [1, 3, 128, 192]) });
  return {
    async run(chw: Float32Array): Promise<NetOutputs> {
      const out = await session.run({ image: new ort.Tensor('float32', chw, [1, 3, 128, 192]) });
      return { seg: out['seg']!.data as Float32Array, ident: out['ident']!.data as Float32Array, kp: out['kp']!.data as Float32Array };
    },
  };
}
